문15. 다음C 언어프로그램의출력결과는?
#include <stdio.h>
int i;
int RecFunc(int n)
{
i++;
if (n <= 1)
return 1;
else
return RecFunc(n-1) + RecFunc(n-2);
}
int main()
{
int result;
i = 0;
result = RecFunc(5);
printf("%d, %d\n", i, result);
}
①13, 5
②13, 8
③15, 5
④15, 8

